export function stability(features,floor=.1){return features.filter(f=>f.resolved).map(f=>{const v=[...f.values].sort((a,b)=>a-b),median=v[Math.floor(v.length/2)],min=v[0],max=v.at(-1);return {...f,min,max,median,rangePP:(max-min)*100,relativeRange:median>0?(max-min)/median*100:Infinity,present:v.filter(x=>x>0&&x*100>=floor).length}}).filter(f=>f.present===f.values.length).sort((a,b)=>a.relativeRange-b.relativeRange||b.median-a.median)}
export function adjacentChanges(features,samples){return samples.slice(1).map((s,i)=>({start:i,end:i+1,days:(Date.parse(s.date)-Date.parse(samples[i].date))/86400000,brayCurtis:features.reduce((sum,f)=>sum+Math.abs(f.values[i+1]-f.values[i]),0)/2}));}
export function treatmentEvents(events,start,end,kind='all'){const unique=new Map();for(const e of events){if(e.category!=='Treatments'||e.date>end||(e.end_date||e.date)<start||(kind!=='all'&&e.subcategory!==kind))continue;const key=[e.title,e.date,e.end_date,e.dose].join('|');if(!unique.has(key))unique.set(key,{...e});}return [...unique.values()].sort((a,b)=>a.title.localeCompare(b.title)||a.date.localeCompare(b.date));}

export function distanceFromFirst(features,samples){return samples.map((s,i)=>({date:s.date,brayCurtis:features.reduce((sum,f)=>sum+Math.abs(f.values[i]-f.values[0]),0)/2}));}
